create table quote_requests (id bigint generated by default as identity primary key, created_at timestamp with time zone not null, updated_at timestamp with time zone not null, customer_id bigint not null references app_users(id), status varchar(32) not null, notes varchar(1000), desired_date date, assignee_id bigint);
create table quote_request_items (id bigint generated by default as identity primary key, created_at timestamp with time zone not null, updated_at timestamp with time zone not null, request_id bigint not null references quote_requests(id), variant_id bigint not null references stone_variants(id), quantity_m2 numeric(19,2) not null, note varchar(1000));
create table quotations (id bigint generated by default as identity primary key, created_at timestamp with time zone not null, updated_at timestamp with time zone not null, request_id bigint not null references quote_requests(id), quote_number varchar(100) not null unique, status varchar(32) not null, valid_until date not null, subtotal numeric(19,2) not null, discount numeric(19,2) not null, tax numeric(19,2) not null, total numeric(19,2) not null, currency varchar(3) not null);
create table quotation_items (id bigint generated by default as identity primary key, created_at timestamp with time zone not null, updated_at timestamp with time zone not null, quotation_id bigint not null references quotations(id), type varchar(32) not null, variant_id bigint references stone_variants(id), description_snapshot varchar(1000) not null, quantity numeric(19,2) not null, unit_price numeric(19,2) not null, line_total numeric(19,2) not null);
create table customer_orders (id bigint generated by default as identity primary key, created_at timestamp with time zone not null, updated_at timestamp with time zone not null, quotation_id bigint not null unique references quotations(id), customer_id bigint not null references app_users(id), order_number varchar(100) not null unique, status varchar(32) not null, total_snapshot numeric(19,2) not null);
create table order_items (id bigint generated by default as identity primary key, created_at timestamp with time zone not null, updated_at timestamp with time zone not null, order_id bigint not null references customer_orders(id), variant_id bigint references stone_variants(id), description_snapshot varchar(1000) not null, quantity numeric(19,2) not null, unit_price numeric(19,2) not null, line_total numeric(19,2) not null);
create table inventory_reservations (id bigint generated by default as identity primary key, created_at timestamp with time zone not null, updated_at timestamp with time zone not null, order_item_id bigint not null references order_items(id), inventory_item_id bigint not null references inventory_items(id), quantity_m2 numeric(19,2) not null, status varchar(32) not null);
create index idx_rfq_customer on quote_requests(customer_id); create index idx_quotation_request on quotations(request_id); create index idx_order_customer on customer_orders(customer_id);
